package photo

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
)

// Dir stores photos as files named by key in one directory.
type Dir struct{ path string }

// NewDir creates the directory if needed.
func NewDir(path string) (*Dir, error) {
	if err := os.MkdirAll(path, 0o750); err != nil {
		return nil, fmt.Errorf("photo dir: %w", err)
	}
	return &Dir{path: path}, nil
}

// keys are generated by the server: a UUID plus ".jpg". Anything else is refused,
// so a key from a URL can never point outside the directory.
var keyPattern = regexp.MustCompile(`^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.jpg$`)

// ErrBadKey: the key is not one this package could have made.
var ErrBadKey = errors.New("bad photo key")

// ValidKey reports whether key has the shape of a stored photo's key.
func ValidKey(key string) bool { return keyPattern.MatchString(key) }

// Save writes data under key atomically (temp file + rename): readers never see half a photo.
func (d *Dir) Save(key string, data []byte) error {
	if !ValidKey(key) {
		return ErrBadKey
	}
	return saveAtomic(d.path, key, data)
}

func saveAtomic(dir, name string, data []byte) error {
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(dir, ".upload-*")
	if err != nil {
		return err
	}
	defer func() { _ = os.Remove(tmp.Name()) }() // no-op after a successful rename
	if _, err := tmp.Write(data); err != nil {
		_ = tmp.Close()
		return err
	}
	if err := tmp.Sync(); err != nil {
		_ = tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), filepath.Join(dir, name))
}

// Open opens the photo stored under key.
func (d *Dir) Open(key string) (*os.File, error) {
	if !ValidKey(key) {
		return nil, ErrBadKey
	}
	return os.Open(filepath.Join(d.path, key)) //nolint:gosec // key validated above
}

// Remove deletes the photo under key and its display copy (used to undo a failed upload).
func (d *Dir) Remove(key string) error {
	if !ValidKey(key) {
		return ErrBadKey
	}
	if err := os.Remove(filepath.Join(d.path, displayDir, key)); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return err
	}
	return os.Remove(filepath.Join(d.path, key))
}
